-- 72_industry_guides.sql — the four industry guides (Learn more pages).
--
-- Every guide has the same structure:
--   overview_md   what the pathway is about (two short paragraphs)
--   outcomes      who it is for + what you can do at the end
--   feature_tour  the four skills with a workplace example, what the dashboard
--                 cards mean, and how to use Learn / Practice / Verification
--                 Studio / Vera / tasks / Progress
--   how_to        first-session checklist (5 steps, 15 minutes), common
--                 mistakes, related FAQ slugs
--   hero_image / body_image  image keys (assets supplied by the visual system)
--
-- Examples follow the scenarios in the README; there are no statistics or
-- citations in this file. Have someone from each domain review the wording.
-- Idempotent: upserts on track_id; newer admin edits are preserved.

INSERT INTO industry_guides (track_id, slug, tagline, overview_md, outcomes, feature_tour, how_to, hero_image, body_image, updated_at)
SELECT it.id, 'finance', 'Check AI-generated numbers before they reach a client.',
$md$Finance runs on numbers that other people rely on. AI can produce a polished summary of a ledger, a forecast or a variance in seconds, and the wording will sound sure even when a figure is wrong.

This pathway teaches you to audit AI output the way a careful finance professional would: tie each figure to its source and period, decide when a person must own the number, and protect client and personal information.$md$,
$j${"who_for":"Final-year commerce and accounting students, graduates, and early-career staff in banking, accounting, treasury and financial services.","by_the_end":["Spot a figure in an AI summary that does not tie back to its source.","Decide when a forecast or report can use AI and when a person must own it.","Recognise privacy and compliance risk in a finance workflow, including POPIA.","Explain your checks in plain words to a colleague or client."]}$j$::jsonb,
$j$[{"key":"skills","title":"The four skills in Finance","items":[{"name":"Verification","example":"An AI-generated gross-profit summary includes revenue from a payment that never arrived.","what_to_check":"Tie every figure to the ledger or statement, and confirm the period and whether cash was actually received."},{"name":"AI Judgement","example":"A team wants AI to write the narrative for a client forecast.","what_to_check":"Decide what AI may draft and what a person must own, such as assumptions and sign-off."},{"name":"Risk & Governance","example":"Client account data is pasted into a public AI tool to speed up a report.","what_to_check":"Ask what personal or confidential data leaves the firm and whether you are allowed to share it."},{"name":"Prompt Design","example":"A vague request returns a variance explanation with no period or source.","what_to_check":"State the period, the data and what a good answer must include. Prompt Design tasks are still being added, so this skill shows on your dashboard without scored tasks for now."}]},{"key":"dashboard","title":"What the dashboard cards mean for this pathway","body_md":"Your **readiness** is how much of the Finance content you have covered and passed. **Next task** is the one thing to do now. **Skill scores** show Verification, AI Judgement, Risk & Governance and Prompt Design separately, so you can see what to work on."},{"key":"features","title":"How to use the app","items":[{"feature":"Learn","body_md":"Open the AI Lab for lessons, recall activities and the Finance capstone. Start with the Finance textbook, then do its recall activities straight away."},{"feature":"Practice","body_md":"Scenario tasks for Verification, AI Judgement and Risk & Governance in Finance. Start with Verification."},{"feature":"Verification Studio","body_md":"Check your own AI-assisted work: paste text, upload a document, add a link or give a citation."},{"feature":"Vera","body_md":"Ask Vera to explain a concept or talk through a scenario. She coaches; she will not hand you answers."},{"feature":"Tasks","body_md":"Your Home screen recommends one task at a time. Pass it, read the feedback, then take the next."},{"feature":"Progress","body_md":"See your readiness, skill scores and your readiness path, which shows the stage you are on and the next step."}]}]$j$::jsonb,
$j${"first_session":[{"step":1,"minutes":2,"title":"Take the Finance tour","body_md":"Open Help and choose Replay welcome tour, or follow the Getting started card on Home."},{"step":2,"minutes":1,"title":"Read your Home screen","body_md":"Tap the info button on a card to see what it measures."},{"step":3,"minutes":6,"title":"Pass your first Verification task","body_md":"Open Practice and start Verification. Read the feedback even if you pass."},{"step":4,"minutes":4,"title":"Open one Learn lesson","body_md":"Read a short lesson in the AI Lab and answer its recall activities."},{"step":5,"minutes":2,"title":"Check Progress","body_md":"See your readiness and the next step on your readiness path."}],"common_mistakes":[{"mistake":"Trusting an answer because it sounds confident.","how_the_app_helps":"Every Verification task hides the answer key and asks you to find and fix the flaw, so you practise checking before believing."},{"mistake":"Picking a decision without a reason.","how_the_app_helps":"AI Judgement and Risk & Governance tasks ask for a decision and a justification, and the justification is part of the marking."},{"mistake":"Doing only the part you like.","how_the_app_helps":"Readiness rewards coverage, and your readiness path moves you through all five stages in order."},{"mistake":"Pasting confidential or personal information into an AI tool.","how_the_app_helps":"Risk & Governance tasks practise spotting this. Verification Studio does not keep your submitted material, but only share what you are allowed to share."},{"mistake":"Treating the readiness score as a grade.","how_the_app_helps":"Progress shows what drives the score, so you can see which area to cover next."}],"related_faqs":["what-does-the-readiness-score-mean","what-are-learn-and-practice-for","what-is-verification-studio"]}$j$::jsonb,
'guide-finance-hero', 'guide-finance-body', '2026-10-22T00:00:00Z'
FROM industry_tracks it WHERE it.name = 'Finance'
ON CONFLICT (track_id) DO UPDATE SET
  slug = EXCLUDED.slug, tagline = EXCLUDED.tagline, overview_md = EXCLUDED.overview_md,
  outcomes = EXCLUDED.outcomes, feature_tour = EXCLUDED.feature_tour, how_to = EXCLUDED.how_to,
  hero_image = EXCLUDED.hero_image, body_image = EXCLUDED.body_image,
  updated_at = EXCLUDED.updated_at
WHERE industry_guides.updated_at <= EXCLUDED.updated_at;

INSERT INTO industry_guides (track_id, slug, tagline, overview_md, outcomes, feature_tour, how_to, hero_image, body_image, updated_at)
SELECT it.id, 'legal', 'Make sure an AI summary cites what it claims to cite.',
$md$Legal work depends on exact sources: the right clause, the right section, a judgment that actually exists. AI can write a convincing case summary that cites something that does not exist.

This pathway teaches you to check citations and claims against official sources, decide when a draft can be AI-assisted and when a lawyer must own it, and protect confidentiality, privilege and personal information.$md$,
$j${"who_for":"Law students, graduates, candidate attorneys and early-career legal and compliance staff.","by_the_end":["Check whether a summary really cites the clause or judgment it claims.","Decide when a draft can be AI-assisted and when it needs a lawyer.","Recognise confidentiality, privilege and POPIA risk before sharing material with an AI tool.","Explain what you checked and what still needs a person."]}$j$::jsonb,
$j$[{"key":"skills","title":"The four skills in Legal","items":[{"name":"Verification","example":"A case summary cites a judgment that does not exist.","what_to_check":"Find the citation in an official source, and confirm the court, date and what it actually held."},{"name":"AI Judgement","example":"A colleague suggests an AI-drafted clause for a client agreement.","what_to_check":"Decide whether AI can produce a first draft and who must review and own the final wording."},{"name":"Risk & Governance","example":"A client file is uploaded to a public AI tool to be summarised.","what_to_check":"Ask about confidentiality, privilege and POPIA before any client information leaves your control."},{"name":"Prompt Design","example":"A broad question returns a general answer that ignores South African law.","what_to_check":"Say the jurisdiction, the document and what you need. Prompt Design tasks are still being added, so this skill shows on your dashboard without scored tasks for now."}]},{"key":"dashboard","title":"What the dashboard cards mean for this pathway","body_md":"Your **readiness** shows how much of the Legal content you have covered and passed. **Next task** is the one thing to do now. **Skill scores** show each skill separately. Interview practice is part of the Legal pathway."},{"key":"features","title":"How to use the app","items":[{"feature":"Learn","body_md":"Open the AI Lab for lessons, recall activities and the Legal capstone. Start with the Legal textbook, then do its recall activities straight away."},{"feature":"Practice","body_md":"Scenario tasks for Verification, AI Judgement and Risk & Governance in Legal. Start with Verification."},{"feature":"Verification Studio","body_md":"Check your own AI-assisted work: paste text, upload a document, add a link or give a citation."},{"feature":"Vera","body_md":"Ask Vera to explain a concept or talk through a scenario. She coaches; she will not hand you answers."},{"feature":"Tasks","body_md":"Your Home screen recommends one task at a time. Pass it, read the feedback, then take the next."},{"feature":"Progress","body_md":"See your readiness, skill scores and your readiness path, which shows the stage you are on and the next step."}]}]$j$::jsonb,
$j${"first_session":[{"step":1,"minutes":2,"title":"Take the Legal tour","body_md":"Open Help and choose Replay welcome tour, or follow the Getting started card on Home."},{"step":2,"minutes":1,"title":"Read your Home screen","body_md":"Tap the info button on a card to see what it measures."},{"step":3,"minutes":6,"title":"Pass your first Verification task","body_md":"Open Practice and start Verification. Read the feedback even if you pass."},{"step":4,"minutes":4,"title":"Open one Learn lesson","body_md":"Read a short lesson in the AI Lab and answer its recall activities."},{"step":5,"minutes":2,"title":"Check Progress","body_md":"See your readiness and the next step on your readiness path."}],"common_mistakes":[{"mistake":"Trusting an answer because it sounds confident.","how_the_app_helps":"Every Verification task hides the answer key and asks you to find and fix the flaw, so you practise checking before believing."},{"mistake":"Picking a decision without a reason.","how_the_app_helps":"AI Judgement and Risk & Governance tasks ask for a decision and a justification, and the justification is part of the marking."},{"mistake":"Doing only the part you like.","how_the_app_helps":"Readiness rewards coverage, and your readiness path moves you through all five stages in order."},{"mistake":"Pasting confidential or personal information into an AI tool.","how_the_app_helps":"Risk & Governance tasks practise spotting this. Verification Studio does not keep your submitted material, but only share what you are allowed to share."},{"mistake":"Treating the readiness score as a grade.","how_the_app_helps":"Progress shows what drives the score, so you can see which area to cover next."}],"related_faqs":["what-is-verification-studio","what-does-the-readiness-score-mean","how-do-i-change-my-industry"]}$j$::jsonb,
'guide-legal-hero', 'guide-legal-body', '2026-10-22T00:00:00Z'
FROM industry_tracks it WHERE it.name = 'Legal'
ON CONFLICT (track_id) DO UPDATE SET
  slug = EXCLUDED.slug, tagline = EXCLUDED.tagline, overview_md = EXCLUDED.overview_md,
