INSERT INTO industry_guides (track_id, slug, tagline, overview_md, outcomes, feature_tour, how_to, hero_image, body_image, updated_at)
SELECT it.id, 'business-consulting', 'Check an AI recommendation against the evidence behind it.',
$md$Consulting turns evidence into advice. AI can draft a confident recommendation, a market view or a client answer that reads well but is not supported by the facts, or that ignores the client's legal obligations.

This pathway teaches you to test recommendations against their evidence, decide when a strategy or client answer can be AI-assisted, and spot bias, privacy and compliance risk in an engagement.$md$,
$j${"who_for":"Business, commerce and management students, graduates, analysts and junior consultants.","by_the_end":["Test an AI recommendation against the evidence it claims to rest on.","Decide when a strategy or client answer can be AI-assisted.","Recognise bias, privacy and compliance risk, including POPIA obligations.","Present your checks and caveats clearly to a client or manager."]}$j$::jsonb,
$j$[{"key":"skills","title":"The four skills in Business Consulting","items":[{"name":"Verification","example":"An AI recommendation states a conclusion that the supplied data does not support.","what_to_check":"Trace each claim to its evidence, and confirm the data, period and method."},{"name":"AI Judgement","example":"A manager wants an AI-written answer sent straight to a client.","what_to_check":"Decide what AI can draft, and what a person must verify and own before it leaves."},{"name":"Risk & Governance","example":"An AI recommendation ignores the client's POPIA obligations.","what_to_check":"Ask what personal information is involved and which legal and ethical duties apply."},{"name":"Prompt Design","example":"A broad request returns generic advice with no client context.","what_to_check":"Give the context, the constraints and the evidence to use. Prompt Design tasks are still being added, so this skill shows on your dashboard without scored tasks for now."}]},{"key":"dashboard","title":"What the dashboard cards mean for this pathway","body_md":"Your **readiness** shows how much of the Business Consulting content you have covered and passed. **Next task** is the one thing to do now. **Skill scores** show each skill separately."},{"key":"features","title":"How to use the app","items":[{"feature":"Learn","body_md":"Open the AI Lab for lessons, recall activities and the Business Consulting capstone. Start with the Business Consulting textbook, then do its recall activities straight away."},{"feature":"Practice","body_md":"Scenario tasks for Verification, AI Judgement and Risk & Governance in Business Consulting. Start with Verification."},{"feature":"Verification Studio","body_md":"Check your own AI-assisted work: paste text, upload a document, add a link or give a citation."},{"feature":"Vera","body_md":"Ask Vera to explain a concept or talk through a scenario. She coaches; she will not hand you answers."},{"feature":"Tasks","body_md":"Your Home screen recommends one task at a time. Pass it, read the feedback, then take the next."},{"feature":"Progress","body_md":"See your readiness, skill scores and your readiness path, which shows the stage you are on and the next step."}]}]$j$::jsonb,
$j${"first_session":[{"step":1,"minutes":2,"title":"Take the Business Consulting tour","body_md":"Open Help and choose Replay welcome tour, or follow the Getting started card on Home."},{"step":2,"minutes":1,"title":"Read your Home screen","body_md":"Tap the info button on a card to see what it measures."},{"step":3,"minutes":6,"title":"Pass your first Verification task","body_md":"Open Practice and start Verification. Read the feedback even if you pass."},{"step":4,"minutes":4,"title":"Open one Learn lesson","body_md":"Read a short lesson in the AI Lab and answer its recall activities."},{"step":5,"minutes":2,"title":"Check Progress","body_md":"See your readiness and the next step on your readiness path."}],"common_mistakes":[{"mistake":"Trusting an answer because it sounds confident.","how_the_app_helps":"Every Verification task hides the answer key and asks you to find and fix the flaw, so you practise checking before believing."},{"mistake":"Picking a decision without a reason.","how_the_app_helps":"AI Judgement and Risk & Governance tasks ask for a decision and a justification, and the justification is part of the marking."},{"mistake":"Doing only the part you like.","how_the_app_helps":"Readiness rewards coverage, and your readiness path moves you through all five stages in order."},{"mistake":"Pasting confidential or personal information into an AI tool.","how_the_app_helps":"Risk & Governance tasks practise spotting this. Verification Studio does not keep your submitted material, but only share what you are allowed to share."},{"mistake":"Treating the readiness score as a grade.","how_the_app_helps":"Progress shows what drives the score, so you can see which area to cover next."}],"related_faqs":["what-does-the-readiness-score-mean","what-is-verification-studio","what-are-learn-and-practice-for"]}$j$::jsonb,
